/**
 * Explainer videos: scripted scenes (explainers.json) merged with narration timings
 * (timings.json, generated by scripts/narration/build_narration.py — do not edit by hand).
 * Validated at module load.
 */
import { z } from "zod";
import { CitationSchema, VerificationStatusSchema, type Citation } from "../schema";
import explainersJson from "./explainers.json";
import timingsJson from "./timings.json";

const ExplainerSceneSchema = z.object({
  id: z.string().min(1),
  /** Key into the scene registry in src/explainers/registry.ts. */
  visual: z.string().min(1),
  /** English narration; captions are its sentences. */
  narration: z.string().min(1),
  citations: z.array(CitationSchema),
});

const ExplainerDefSchema = z.object({
  id: z.string().min(1),
  kind: z.enum(["protocol", "drug"]),
  protocolId: z.string().min(1),
  drugIds: z.array(z.string().min(1)),
  titleHe: z.string().min(1),
  titleEn: z.string().min(1),
  verificationStatus: VerificationStatusSchema,
  unverifiedReason: z.string().min(1),
  scenes: z.array(ExplainerSceneSchema).min(1),
});

export const ExplainersFileSchema = z.object({
  /** [spoken, display] pairs applied in order (case-sensitive) to captions and chapter text. */
  captionReplacements: z.array(z.tuple([z.string().min(1), z.string()])),
  explainers: z.array(ExplainerDefSchema),
});

const SentenceTimingSchema = z.object({
  text: z.string().min(1),
  startMs: z.number().nonnegative(),
  endMs: z.number().nonnegative(),
});

const SceneTimingSchema = z.object({
  id: z.string().min(1),
  startMs: z.number().nonnegative(),
  endMs: z.number().nonnegative(),
  sentences: z.array(SentenceTimingSchema),
  textSha256: z.string().regex(/^[0-9a-f]{64}$/),
});

const ExplainerTimingsSchema = z.object({
  durationMs: z.number().positive(),
  /** Relative to the app base URL, e.g. "explainers/<id>.m4a". */
  audio: z.string().min(1),
  scenes: z.array(SceneTimingSchema).min(1),
});

export const TimingsFileSchema = z.record(z.string(), ExplainerTimingsSchema);

export type ExplainerScene = z.infer<typeof ExplainerSceneSchema>;
export type ExplainerDef = z.infer<typeof ExplainerDefSchema>;
export type SentenceTiming = z.infer<typeof SentenceTimingSchema>;
export type SceneTiming = z.infer<typeof SceneTimingSchema>;
export type ExplainerTimings = z.infer<typeof ExplainerTimingsSchema>;
export type Explainer = ExplainerDef & { timing: ExplainerTimings };

const EXPLAINERS_FILE = ExplainersFileSchema.parse(explainersJson);
export const EXPLAINER_DEFS: readonly ExplainerDef[] = EXPLAINERS_FILE.explainers;
const CAPTION_REPLACEMENTS = EXPLAINERS_FILE.captionReplacements;

/** Narration is written for speech; this turns a spoken sentence into its on-screen form. */
export function displayText(text: string): string {
  return CAPTION_REPLACEMENTS.reduce((acc, [spoken, display]) => acc.replaceAll(spoken, display), text);
}
export const TIMINGS: Readonly<Record<string, ExplainerTimings>> = TimingsFileSchema.parse(timingsJson);

/** Explainers that have timings. A def without timings is reported by the content test. */
export const EXPLAINERS: readonly Explainer[] = EXPLAINER_DEFS.flatMap((def) => {
  const timing = TIMINGS[def.id];
  return timing === undefined ? [] : [{ ...def, timing }];
});

export function getExplainer(id: string): Explainer | undefined {
  return EXPLAINERS.find((e) => e.id === id);
}

export function explainerForProtocol(protocolId: string): Explainer | undefined {
  return EXPLAINERS.find((e) => e.kind === "protocol" && e.protocolId === protocolId);
}

export function explainerForDrug(protocolId: string, drugId: string): Explainer | undefined {
  return EXPLAINERS.find(
    (e) => e.kind === "drug" && e.protocolId === protocolId && e.drugIds.includes(drugId),
  );
}

/** All scene citations, deduplicated by source and locator. */
export function explainerCitations(e: Explainer): Citation[] {
  const seen = new Set<string>();
  const out: Citation[] = [];
  for (const s of e.scenes) {
    for (const c of s.citations) {
      const key = `${c.sourceId}\u0000${c.locator}`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(c);
    }
  }
  return out;
}
